  if (typeof value === "number") {
    return value % 1 === 0;
  } else if (typeof value === "string") {
    const numberValue = parseInt(value, 10);
    return (
      !Number.isNaN(numberValue) &&
      numberValue % 1 === 0 &&
      numberValue.toString() === value
    );
  }

  return false;
}

